// Єдиний формат вхідних даних для message та callback_query
const u = $input.first().json;
const m = u.message || {};
const cq = u.callback_query || null;
const from = m.from || (cq && cq.from) || {};
return [{ json: {
  update_id: u.update_id || 0,
  kind: cq ? 'callback' : 'message',
  chat_id: m.chat?.id ?? cq?.message?.chat?.id,
  user_id: from.id,
  first_name: from.first_name || '',
  username: from.username || '',
  text: (m.text || '').trim(),
  callback_data: cq?.data || '',
  callback_id: cq?.id || '',
  has_voice: !!m.voice,
  voice_file_id: m.voice?.file_id || '',
  is_admin: String(from.id) === String(u.admin_chat_id),
  admin_chat_id: u.admin_chat_id,
  rate_limit_per_hour: u.rate_limit_per_hour,
    daily_limit: u.daily_limit
} }];

// Налаштування користувача (Data Table), дедуплікація, ліміт запитів і зміни /image /audio, кнопки режиму та мови
const j = $('Normalize Update').first().json;
const row = $input.first().json || {};
const now = Date.now();
const MODES = { text: '💬 Текст', image: '🎨 Картинка', code: '💻 Код', email: '✉️ Лист', skill: '🧩 Skill' };
const LANGS = { auto: '🌐 Авто', uk: '🇺🇦 Українська', en: '🇬🇧 English', ru: 'Русский' };
const TARGETS = { auto: '🤖 Авто', chatgpt: 'ChatGPT', claude: 'Claude', gemini: 'Gemini' };
const isNew = !row.user_id;
const source = j.kind === 'callback' ? 'button' : (j.has_voice ? 'voice' : 'text');
const p = {
  mode: MODES[row.mode] ? row.mode : 'text',
  lang: LANGS[row.lang] ? row.lang : 'auto',
  target: TARGETS[row.target] ? row.target : '',
  pending_prompt: String(row.pending_prompt || ''),
  clarify: row.clarify === true || row.clarify === 'true',
  image: (row.image === undefined || row.image === null || row.image === '') ? false : (row.image === true || row.image === 'true'),
  audio: row.audio === true || row.audio === 'true',
  last_image_prompt: row.last_image_prompt || '',
  window_start: Number(row.window_start) || now,
  hits: Number(row.hits) || 0,
  day_start: Number(row.day_start) || now,
  day_hits: Number(row.day_hits) || 0,
  last_update_id: Number(row.last_update_id) || 0
};
// Telegram повторно надсилає апдейт при таймауті: ігноруємо вже оброблені update_id
const dup = !!(j.update_id && p.last_update_id && j.update_id <= p.last_update_id);
if (now - p.window_start > 3600000) { p.window_start = now; p.hits = 0; }
if (now - p.day_start > 86400000) { p.day_start = now; p.day_hits = 0; }
const isAction = j.kind === 'callback' && /^act:/.test(j.callback_data);
const isPrompt = isAction || (j.kind === 'message' && (j.has_voice || (j.text && !j.text.startsWith('/') && !/^(ілля|илья)/i.test(j.text))));
const limit = Number(j.rate_limit_per_hour) || 20;
const dayLimit = Number(j.daily_limit) || 60;
let limitKind = '';
let allowed = true;
let reply = '';
let resumePrompt = '';
if (!dup) {
  if (isPrompt) {
    if (p.hits >= limit) { allowed = false; limitKind = 'hour'; }
    else if (p.day_hits >= dayLimit) { allowed = false; limitKind = 'day'; }
    else { p.hits++; p.day_hits++; }
  }
  const cmd = j.text.startsWith('/') ? ((j.text.match(/^\/(\w+)/) || [])[1] || '').toLowerCase() : '';
  if (cmd === 'image') {
    p.image = !p.image;
    reply = `${p.image ? '✅' : '🚫'} Картинки: ${p.image ? 'увімкнено' : 'вимкнено'}. Змінити: /image`;
  } else if (cmd === 'clarify') {
    p.clarify = !p.clarify;
    reply = `${p.clarify ? '✅' : '🚫'} Уточнення: ${p.clarify ? 'увімкнено (бот спершу поставить 1–3 питання, якщо запит розмитий)' : 'вимкнено (промт одразу)'}. Змінити: /clarify`;
  } else if (cmd === 'audio') {
    p.audio = !p.audio;
    reply = `${p.audio ? '✅' : '🚫'} Аудіо: ${p.audio ? 'увімкнено' : 'вимкнено'}. Змінити: /audio`;
  } else if (j.kind === 'callback' && j.callback_data.startsWith('mode:')) {
    const v = j.callback_data.slice(5);
    if (MODES[v]) { p.mode = v; reply = `✅ Режим: ${MODES[v]}`; }
  } else if (j.kind === 'callback' && j.callback_data.startsWith('target:')) {
    const v = j.callback_data.slice(7);
    if (TARGETS[v]) {
      p.target = v; reply = `✅ Промт готуємо під: ${TARGETS[v]}`;
      if (p.pending_prompt) { resumePrompt = p.pending_prompt; p.pending_prompt = ''; }
    }
  } else if (j.kind === 'callback' && j.callback_data.startsWith('lang:')) {
    const v = j.callback_data.slice(5);
    if (LANGS[v]) { p.lang = v; reply = `✅ Мова: ${LANGS[v]}`; }
  }
}
if (j.update_id) p.last_update_id = Math.max(p.last_update_id, j.update_id);
const ACTIONS = {
  'act:redo': 'Перероби свій попередній промт: запропонуй інший підхід, збережи тему та формат JSON.',
  'act:short': 'Зроби свій попередній промт коротшим і лаконічнішим, збережи суть та формат JSON.',
  'act:long': 'Зроби свій попередній промт детальнішим: додай контекст, обмеження та приклади, збережи формат JSON.'
};
const rt = /^act:to_([a-z]+)$/.exec(j.callback_data || '');
const retarget = rt && TARGETS[rt[1]] && rt[1] !== 'auto' ? rt[1] : '';
const retargetPrompt = retarget ? `Переоформи свій попередній промт під цільову модель ${TARGETS[retarget]}: збережи зміст, зміни лише структуру та оформлення; формат JSON той самий.` : '';
return [{ json: { ...j, p, mode: p.mode, lang: p.lang, target: p.target || 'auto', target_set: !!p.target, clarify: p.clarify, resume_prompt: resumePrompt, want_image: p.image, want_audio: p.audio,
  last_image_prompt: p.last_image_prompt, dup, allowed, limit_kind: limitKind, reply, prompt_override: ACTIONS[j.callback_data] || retargetPrompt, target_override: retarget,
  is_new: isNew, started_at: now, source } }];

