// Статистика для адміна за анонімним логом (без імен і текстів)
const rows = $input.all().map(i => i.json).filter(r => r.event);
const chat = $('Normalize Update').first().json.chat_id;
const now = Date.now();
const H = 36e5, D = 864e5;
const ts = r => new Date(r.createdAt).getTime();
const ev = (e, ms) => rows.filter(r => r.event === e && now - ts(r) < ms);
const uniq = a => new Set(a.map(r => r.user_id)).size;
const count = (a, f) => { const m = {}; a.forEach(r => { const k = f(r) || '-'; m[k] = (m[k] || 0) + 1; }); return Object.keys(m).length ? Object.entries(m).map(([k, v]) => `${k}: ${v}`).join(', ') : 'немає'; };
const p1h = ev('prompt', H), p1 = ev('prompt', D), p7 = ev('prompt', 7 * D);
const all = rows.filter(r => r.event === 'prompt');
const bad = p1.filter(r => r.result === 'model_error').length;
const clar = p1.filter(r => r.result === 'clarify').length;
const dur = p1.map(r => Number(r.duration_ms) || 0).filter(x => x > 0);
const avg = dur.length ? (dur.reduce((a, b) => a + b, 0) / dur.length / 1000).toFixed(1) : '-';
const first = {};
rows.forEach(r => { const t = ts(r); if (!(r.user_id in first) || t < first[r.user_id]) first[r.user_id] = t; });
const newU = new Set(p1.map(r => r.user_id).filter(id => now - first[id] < D)).size;
const text = [
  '📊 Статистика бота',
  `Запитів: за годину ${p1h.length}, за 24 год ${p1.length}, за 7 днів ${p7.length}`,
  `Користувачів: 24 год ${uniq(p1)} (нових ${newU}), 7 днів ${uniq(p7)}, усього ${uniq(all)}`,
  `Помилок моделі за 24 год: ${bad} із ${p1.length}; уточнень: ${clar}; середній час відповіді: ${avg} с`,
  `Вхід: ${count(p1, r => r.source)}`,
  `Режими: ${count(p1, r => r.mode)}`,
  `Мови: ${count(p1, r => r.lang)}`,
  `Кнопки: ${count(p1.filter(r => r.button), r => String(r.button).replace('act:', ''))}`,
  `Оцінки за 24 год: 👍 ${ev('feedback_up', D).length}, 👎 ${ev('feedback_down', D).length}`,
  `Збої картинки ${ev('image_error', D).length}, озвучки ${ev('tts_error', D).length}; ліміт спрацював ${ev('rate_limited', D).length}`,
  `Повідомлень автору за 24 год: ${ev('admin_message', D).length}`
].join('\n');
return [{ json: { chat_id: chat, text } }];

// Після Whisper втрачається контекст: повертаємо його та кладемо розшифровку в prompt_text
const base = $('Apply Limits And Settings').first().json;
const r = $input.first().json || {};
const parts = r.content?.parts || r.candidates?.[0]?.content?.parts || [];
const t = r.text || parts.map(p => p.audioTranscription?.text || p.text || '').join(' ').trim() || (typeof r.output === 'string' ? r.output : '');
return [{ json: { ...base, prompt_text: String(t || '').trim() } }];

// Витягуємо JSON з відповіді моделі; при збої віддаємо зрозуміле повідомлення
const base = $('Apply Limits And Settings').first().json;
const raw = $input.first().json.output;
let text = '', img = '', parsed = false, questions = [], gotPrompt = false, skillName = '';
if (typeof raw === 'string' && raw.trim()) {
  // режим skill: агент повертає чистий SKILL.md (без JSON), інакше розбираємо JSON
  const sk = raw.trim().replace(/^```(?:markdown|md)?[ \t]*\r?\n/, '').replace(/\r?\n```[ \t]*$/, '');
  if (base.mode === 'skill' && /^---\r?\n/.test(sk)) {
    text = sk;
    gotPrompt = true;
    parsed = true;
  } else try {
    const m = raw.match(/\{[\s\S]*\}/);
    const p = JSON.parse(m ? m[0] : raw);
    text = p.text_response || '';
    gotPrompt = !!String(text).trim();
    img = p.image_prompt || '';
    skillName = String(p.skill_name || '').trim();
    questions = Array.isArray(p.questions) ? p.questions.map(q => String(q).trim()).filter(Boolean).slice(0, 3) : [];
    parsed = true;
  } catch (e) {
    text = raw; // модель відповіла не JSON: показуємо як є, без картинки
  }
}
if (questions.length && !String(text).trim()) {
  text = '🧐 Щоб зробити точний промт, дай відповідь одним повідомленням:\n' + questions.map((q, i) => `${i + 1}. ${q}`).join('\n');
}
const isQuestions = questions.length > 0 && !gotPrompt;
const ok = !!String(text).trim();
// скіл лише якщо відповідь справді починається з frontmatter; інакше (наприклад, відмова моделі) показуємо звичайним текстом
const isSkill = base.mode === 'skill' && ok && !isQuestions && /^---\r?\n/.test(String(text));
const isPlain = base.mode === 'skill' && ok && !isQuestions && !isSkill;
const skillMd = isSkill ? String(text) : '';
const skillWarnings = [];
if (isSkill) {
  // Перевірка за специфікацією Agent Skills (agentskills.io): frontmatter, name, description, розмір
  const fm = skillMd.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!fm) {
    skillWarnings.push('немає блоку frontmatter між рядками ---');
  } else {
    const clean = v => String(v || '').trim().replace(/^["']|["']$/g, '');
    const nm = fm[1].match(/^name:[ \t]*(.*)$/m);
    const dm = fm[1].match(/^description:[ \t]*(.*)$/m);
    const name = clean(nm && nm[1]);
    let desc = clean(dm && dm[1]);
    if (dm && /^[>|][+-]?$/.test(desc)) {
      desc = ((fm[1].slice(dm.index + dm[0].length).replace(/^\r?\n/, '').match(/^(?:[ \t]+.*\n?)+/) || [''])[0]).replace(/\s+/g, ' ').trim();
    }
    if (name) skillName = name;
    if (!name) skillWarnings.push('немає поля name');
    else if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(name) || name.length > 64) skillWarnings.push('name: лише a-z, 0-9 та дефіси (без -- і дефісів по краях), до 64 символів');
    if (!desc) skillWarnings.push('немає поля description');
    else {
      if (desc.length > 1024) skillWarnings.push(`description має ${desc.length} символів (максимум 1024)`);
      if (!/(when|use this|use for|use it|if the user|використовуй|застосовуй|підключай|коли|якщо)/i.test(desc)) skillWarnings.push('у description не видно, коли застосовувати скіл');
    }
  }
  const lines = skillMd.split('\n').length;
  if (lines > 500) skillWarnings.push(`у файлі ${lines} рядків (рекомендовано до 500)`);
  if (skillWarnings.length) text = skillMd + '\n\n⚠️ Перевір перед використанням:\n- ' + skillWarnings.join('\n- ');
}
// модель іноді пропускає image_prompt: тоді будуємо запасний опис із запиту користувача
if (ok && !isQuestions && !isSkill && !String(img).trim() && parsed) {
  const q = String($('Has Prompt Text?').first().json.prompt_text || '').slice(0, 200);
  img = q ? `Clean modern illustration for: ${q}, high quality, 4k` : '';
}
if (!ok) text = 'Не вдалося сформувати промт. Спробуй ще раз трохи пізніше.';
return [{ json: {
  ...base,
  ok,
  text_response: String(text),
  image_prompt: isSkill ? '' : String(img),
  is_skill: isSkill,
  is_plain: isPlain,
  skill_name: skillName,
  skill_md: skillMd,
  skill_warnings: skillWarnings,
  is_questions: isQuestions,
  want_image: !!(base.want_image && ok && img && !isQuestions && base.mode !== 'skill'),
  want_audio: !!(base.want_audio && ok && !isQuestions && base.mode !== 'skill')
} }];

// Telegram: максимум 4096 символів і HTML-екранування. Ріжемо по 3500 символів, кнопки лише під останньою частиною
const j = $input.first().json;
const esc = s => s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const name = esc(j.first_name || '');
if (!j.ok || j.is_questions || j.is_plain) return [{ json: { chat_id: j.chat_id, html: esc(j.text_response), with_buttons: false } }];
const chunks = [];
for (let i = 0; i < j.text_response.length; i += 3500) chunks.push(j.text_response.slice(i, i + 3500));
const footer = '\n\n---\n🦾 Тобі сподобався результат?\nПідтримай проект, щоб він мав змогу існувати: /donate';
return chunks.map((c, i) => ({ json: {
  chat_id: j.chat_id,
  with_buttons: i === chunks.length - 1,
  html: (i === 0 ? `Привіт, <b>${name}</b>! 👋\n\n${j.is_skill ? 'Ось твій SKILL.md:' : 'Ось твій промт:'}\n\n` : '') + `<code>${esc(c)}</code>` + (i === chunks.length - 1 ? footer : '')
} }));

// Gemini TTS повертає сирий PCM (16 біт, mono): додаємо WAV-заголовок. Якщо аудіо немає, гілка тихо завершується
const j = $input.first().json;
const part = j.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
if (!part) return [{ json: { no_audio: true } }];
const pcm = Buffer.from(part.inlineData.data, 'base64');
const rate = Number((String(part.inlineData.mimeType).match(/rate=(\d+)/) || [])[1]) || 24000;
const h = Buffer.alloc(44);
h.write('RIFF', 0); h.writeUInt32LE(36 + pcm.length, 4); h.write('WAVE', 8); h.write('fmt ', 12);
h.writeUInt32LE(16, 16); h.writeUInt16LE(1, 20); h.writeUInt16LE(1, 22); h.writeUInt32LE(rate, 24);
h.writeUInt32LE(rate * 2, 28); h.writeUInt16LE(2, 32); h.writeUInt16LE(16, 34); h.write('data', 36); h.writeUInt32LE(pcm.length, 40);
const bin = await this.helpers.prepareBinaryData(Buffer.concat([h, pcm]), 'speech.wav', 'audio/wav');
return [{ json: {}, binary: { data: bin } }];
